 pub fn add_mesh(&mut self,mesh:&Mesh,capacity:usize)->Result<usize>{unsafe{let mut vb=None;let desc=D3D11_BUFFER_DESC{ByteWidth:(mesh.vertices.len()*size_of::<Vertex>())as u32,Usage:D3D11_USAGE_IMMUTABLE,BindFlags:D3D11_BIND_VERTEX_BUFFER.0 as u32,..Default::default()};let init=D3D11_SUBRESOURCE_DATA{pSysMem:mesh.vertices.as_ptr().cast(),..Default::default()};self.device.CreateBuffer(&desc,Some(&init),Some(&mut vb))?;let capacity=capacity.max(mesh.instances.len()).max(1);let mut ib=None;self.device.CreateBuffer(&D3D11_BUFFER_DESC{ByteWidth:(capacity*size_of::<Instance>())as u32,Usage:D3D11_USAGE_DYNAMIC,BindFlags:D3D11_BIND_VERTEX_BUFFER.0 as u32,CPUAccessFlags:D3D11_CPU_ACCESS_WRITE.0 as u32,..Default::default()},None,Some(&mut ib))?;let id=self.batches.len();self.batches.push(Batch{name:mesh.name.clone(),vb:vb.unwrap(),ib:ib.unwrap(),vertices:mesh.vertices.len()as u32,count:0,capacity,blend:mesh.blend,depth_write:mesh.depth_write,depth_test:mesh.depth_test,enabled:true});self.update(id,&mesh.instances)?;self.order=(0..self.batches.len()).collect();self.order.sort_by_key(|&i|{let b=&self.batches[i];let layer=if b.name.starts_with("live"){b.name.as_bytes()[4].saturating_sub(48)as i32}else if b.name=="hud"{9}else if b.name=="killFeed"{10}else if ["playerPanels","unitLabels","miniDots"].contains(&b.name.as_str()){8}else if b.name.starts_with("bushT")||b.name=="bushSide"||b.name=="projectiles"{8}else if b.name=="rings"{7}else if b.name=="shadows"{6}else{0};(b.blend as u8,layer)});self.batch_sorts.set(self.batch_sorts.get()+1);Ok(id)}}
 pub fn update(&mut self,id:usize,instances:&[Instance])->Result<()>{let b=&mut self.batches[id];if instances.len()>b.capacity{bail!("고정 인스턴스 용량 초과: {}",b.name);}b.count=instances.len()as u32;if instances.is_empty(){return Ok(());}unsafe{let mut map=D3D11_MAPPED_SUBRESOURCE::default();self.context.Map(&b.ib,0,D3D11_MAP_WRITE_DISCARD,0,Some(&mut map))?;std::ptr::copy_nonoverlapping(instances.as_ptr().cast::<u8>(),map.pData.cast(),std::mem::size_of_val(instances));self.context.Unmap(&b.ib,0);}Ok(())}
 pub fn update_hud(&self,pixels:&[u8])->Result<()>{let w=self.settings.hud_width;let h=w*crate::hud::CANVAS_HEIGHT/1024;if pixels.len()!=(w*h*4)as usize{bail!("HUD 크기 오류");}let t=Instant::now();let image=image::RgbaImage::from_raw(w,h,pixels.to_vec()).unwrap();let premult=crate::mips::premultiply(&image);let pack=t.elapsed().as_secs_f64()*1000.0;let t=Instant::now();unsafe{self.context.UpdateSubresource(&self.hud,0,None,premult.as_ptr().cast(),w*4,0);}let transfer=t.elapsed().as_secs_f64()*1000.0;let t=Instant::now();unsafe{self.context.GenerateMips(&self.hud_view);}self.hud_times.set([pack,transfer,t.elapsed().as_secs_f64()*1000.0]);self.hud_uploads.set(self.hud_uploads.get()+1);Ok(())}
 pub fn update_hud_regions(&self,pixels:&[u8],regions:&[crate::hud_stream::Rect])->Result<()>{let w=self.settings.hud_width;let h=w*crate::hud::CANVAS_HEIGHT/1024;if pixels.len()!=(w*h*4)as usize{bail!("HUD 영역 크기 오류");}self.hud_times.set([0.0;3]);if regions.is_empty(){return Ok(());}let t=Instant::now();for r in regions{if r.right>w||r.bottom>h||r.right<=r.left||r.bottom<=r.top{bail!("HUD 영역 범위 오류");}let box_=D3D11_BOX{left:r.left,top:r.top,front:0,right:r.right,bottom:r.bottom,back:1};unsafe{self.context.UpdateSubresource(&self.hud,0,Some(&box_),pixels.as_ptr().add(((r.top*w+r.left)*4)as usize).cast(),w*4,0);}}let transfer=t.elapsed().as_secs_f64()*1000.0;let t=Instant::now();unsafe{self.context.GenerateMips(&self.hud_view);}self.hud_times.set([0.0,transfer,t.elapsed().as_secs_f64()*1000.0]);self.hud_uploads.set(self.hud_uploads.get()+1);Ok(())}
 pub fn target(&self,texture:&ID3D11Texture2D,width:u32,height:u32,format:DXGI_FORMAT)->Result<Target>{self.target_samples(texture,width,height,format,self.settings.msaa_samples)}
 pub fn target_samples(&self,texture:&ID3D11Texture2D,width:u32,height:u32,format:DXGI_FORMAT,requested:u32)->Result<Target>{unsafe{let quality=self.device.CheckMultisampleQualityLevels(format,requested)?;let samples=if quality>0{requested}else{1};if requested!=samples{self.log.line("요청 MSAA 미지원: 단일 샘플로 대체");}let cached=self.surface.borrow().as_ref().filter(|s|s.width==width&&s.height==height&&s.format==format&&s.samples==samples).cloned();let surface=if let Some(s)=cached{s}else{let mut color=None;self.device.CreateTexture2D(&D3D11_TEXTURE2D_DESC{Width:width,Height:height,MipLevels:1,ArraySize:1,Format:if format==DXGI_FORMAT_R8G8B8A8_UNORM_SRGB||format==DXGI_FORMAT_R8G8B8A8_UNORM{DXGI_FORMAT_R8G8B8A8_TYPELESS}else{DXGI_FORMAT_B8G8R8A8_TYPELESS},SampleDesc:DXGI_SAMPLE_DESC{Count:samples,Quality:0},Usage:D3D11_USAGE_DEFAULT,BindFlags:D3D11_BIND_RENDER_TARGET.0 as u32,..Default::default()},None,Some(&mut color))?;let color=color.unwrap();let mut view=None;let rtv=D3D11_RENDER_TARGET_VIEW_DESC{Format:format,ViewDimension:if samples>1{D3D11_RTV_DIMENSION_TEXTURE2DMS}else{D3D11_RTV_DIMENSION_TEXTURE2D},Anonymous:D3D11_RENDER_TARGET_VIEW_DESC_0{Texture2D:D3D11_TEX2D_RTV{MipSlice:0}}};self.device.CreateRenderTargetView(&color,Some(&rtv),Some(&mut view))?;let mut depth=None;self.device.CreateTexture2D(&D3D11_TEXTURE2D_DESC{Width:width,Height:height,MipLevels:1,ArraySize:1,Format:DXGI_FORMAT_D32_FLOAT,SampleDesc:DXGI_SAMPLE_DESC{Count:samples,Quality:0},Usage:D3D11_USAGE_DEFAULT,BindFlags:D3D11_BIND_DEPTH_STENCIL.0 as u32,..Default::default()},None,Some(&mut depth))?;let mut dsv=None;self.device.CreateDepthStencilView(depth.as_ref().unwrap(),None,Some(&mut dsv))?;let s=Surface{width,height,format,samples,color,view:view.unwrap(),depth:dsv.unwrap()};*self.surface.borrow_mut()=Some(s.clone());s};let mut dest=D3D11_TEXTURE2D_DESC::default();texture.GetDesc(&mut dest);let resolve_format=if dest.Format==DXGI_FORMAT_R8G8B8A8_TYPELESS||dest.Format==DXGI_FORMAT_B8G8R8A8_TYPELESS{format}else{dest.Format};Ok(Target{view:surface.view,depth:surface.depth,width,height,resolve:Some((texture.clone(),surface.color,resolve_format)),samples})}}
 pub fn offscreen(&self,width:u32,height:u32)->Result<(ID3D11Texture2D,Target)>{self.offscreen_samples(width,height,self.settings.msaa_samples)}
 pub fn offscreen_samples(&self,width:u32,height:u32,samples:u32)->Result<(ID3D11Texture2D,Target)>{unsafe{let mut texture=None;self.device.CreateTexture2D(&D3D11_TEXTURE2D_DESC{Width:width,Height:height,MipLevels:1,ArraySize:1,Format:DXGI_FORMAT_R8G8B8A8_TYPELESS,SampleDesc:DXGI_SAMPLE_DESC{Count:1,Quality:0},Usage:D3D11_USAGE_DEFAULT,BindFlags:D3D11_BIND_RENDER_TARGET.0 as u32,..Default::default()},None,Some(&mut texture))?;let texture=texture.unwrap();let target=self.target_samples(&texture,width,height,DXGI_FORMAT_R8G8B8A8_UNORM_SRGB,samples)?;Ok((texture,target))}}
 pub fn render(&mut self,target:&Target,vp:Mat4,world:Mat4,clear:bool){unsafe{let c=&self.context;let mut values=[0.0f32;36];values[..16].copy_from_slice(&vp.to_cols_array());values[16..32].copy_from_slice(&world.to_cols_array());values[32]=if self.quality{1.0}else{0.0};values[33]=target.height as f32;values[34]=self.settings.minimum_line_pixels;c.UpdateSubresource(&self.constants,0,None,values.as_ptr().cast(),0,0);c.OMSetRenderTargets(Some(&[Some(target.view.clone())]),&target.depth);if clear{c.ClearRenderTargetView(&target.view,&[0.035,0.055,0.065,1.0]);c.ClearDepthStencilView(&target.depth,D3D11_CLEAR_DEPTH.0,1.0,0);}c.RSSetViewports(Some(&[D3D11_VIEWPORT{Width:target.width as f32,Height:target.height as f32,MinDepth:0.0,MaxDepth:1.0,..Default::default()}]));c.RSSetState(&self.raster);c.IASetInputLayout(&self.layout);c.IASetPrimitiveTopology(D3D_PRIMITIVE_TOPOLOGY_TRIANGLELIST);c.VSSetShader(&self.vs,None);c.PSSetShader(&self.ps,None);c.VSSetConstantBuffers(0,Some(&[Some(self.constants.clone())]));c.PSSetConstantBuffers(0,Some(&[Some(self.constants.clone()),Some(self.bush_constants.clone())]));let pages:[Option<ID3D11ShaderResourceView>;3]=if self.live{std::array::from_fn(|i|self.live_atlas[i].as_ref().map(|v|v.1.clone()))}else{self.atlas.clone()};c.PSSetShaderResources(0,Some(&[pages[0].clone(),Some(self.hud_view.clone()),pages[1].clone(),pages[2].clone(),self.panel.clone()]));c.PSSetSamplers(0,Some(&[Some(self.sampler.clone()),Some(self.point.clone())]));self.calls=0;for &i in &self.order{let b=&self.batches[i];if b.count==0||!b.enabled||(b.name.starts_with("live")!=self.live&&b.name!="table"&&b.name!="handMarkers"){continue;}c.PSSetShader(if b.blend{&self.ps}else{&self.ps_opaque},None);c.OMSetBlendState(if b.blend{&self.blend_on}else{&self.blend_off},None,u32::MAX);c.OMSetDepthStencilState(if !b.depth_test{&self.depth_off}else if b.depth_write{&self.depth_on}else{&self.depth_read},0);let buffers=[Some(b.vb.clone()),Some(b.ib.clone())];let strides=[size_of::<Vertex>()as u32,size_of::<Instance>()as u32];let offsets=[0u32,0];c.IASetVertexBuffers(0,2,Some(buffers.as_ptr()),Some(strides.as_ptr()),Some(offsets.as_ptr()));c.DrawInstanced(b.vertices,b.count,0,0);self.calls+=1;}c.OMSetRenderTargets(None,None);if let Some((dest,src,format))=&target.resolve{if target.samples>1{c.ResolveSubresource(dest,0,src,0,*format);}else{c.CopyResource(dest,src);}}}}
 pub fn save_png(&self,texture:&ID3D11Texture2D,path:&std::path::Path)->Result<()>{unsafe{let mut desc=D3D11_TEXTURE2D_DESC::default();texture.GetDesc(&mut desc);desc.Usage=D3D11_USAGE_STAGING;desc.BindFlags=0;desc.CPUAccessFlags=D3D11_CPU_ACCESS_READ.0 as u32;let mut staging=None;self.device.CreateTexture2D(&desc,None,Some(&mut staging))?;let staging=staging.unwrap();self.context.CopyResource(&staging,texture);let mut map=D3D11_MAPPED_SUBRESOURCE::default();self.context.Map(&staging,0,D3D11_MAP_READ,0,Some(&mut map))?;let mut bytes=vec![0u8;(desc.Width*desc.Height*4)as usize];for y in 0..desc.Height as usize{let row=slice::from_raw_parts((map.pData as *const u8).add(y*map.RowPitch as usize),desc.Width as usize*4);bytes[y*desc.Width as usize*4..(y+1)*desc.Width as usize*4].copy_from_slice(row);}self.context.Unmap(&staging,0);std::fs::create_dir_all(path.parent().unwrap())?;let mut encoder=png::Encoder::new(std::io::BufWriter::new(std::fs::File::create(path)?),desc.Width,desc.Height);encoder.set_color(png::ColorType::Rgba);encoder.set_depth(png::BitDepth::Eight);encoder.write_header()?.write_image_data(&bytes)?;Ok(())}}
 pub fn panel_image(&mut self,im:&image::RgbaImage)->Result<()>{unsafe{let chain=crate::mips::chain(im);let desc=D3D11_TEXTURE2D_DESC{Width:im.width(),Height:im.height(),MipLevels:chain.len()as u32,ArraySize:1,Format:DXGI_FORMAT_R8G8B8A8_UNORM_SRGB,SampleDesc:DXGI_SAMPLE_DESC{Count:1,Quality:0},Usage:D3D11_USAGE_IMMUTABLE,BindFlags:D3D11_BIND_SHADER_RESOURCE.0 as u32,..Default::default()};let data:Vec<_>=chain.iter().map(|p|D3D11_SUBRESOURCE_DATA{pSysMem:p.as_ptr().cast(),SysMemPitch:p.width()*4,SysMemSlicePitch:0}).collect();let mut t=None;self.device.CreateTexture2D(&desc,Some(data.as_ptr()),Some(&mut t))?;let mut v=None;self.device.CreateShaderResourceView(t.as_ref().unwrap(),None,Some(&mut v))?;self.panel=v;Ok(())}}
 /// 실시간 장면용 동적 텍스처 배열(128·256·2048).
 pub fn live_init(&mut self,slices:[u32;3])->Result<()>{unsafe{for(group,size)in crate::mips::BUCKETS.into_iter().enumerate(){let levels=size.ilog2()+1;let desc=D3D11_TEXTURE2D_DESC{Width:size,Height:size,MipLevels:levels,ArraySize:slices[group],Format:DXGI_FORMAT_R8G8B8A8_UNORM_SRGB,SampleDesc:DXGI_SAMPLE_DESC{Count:1,Quality:0},Usage:D3D11_USAGE_DEFAULT,BindFlags:D3D11_BIND_SHADER_RESOURCE.0 as u32,..Default::default()};let mut texture=None;self.device.CreateTexture2D(&desc,None,Some(&mut texture))?;let texture=texture.unwrap();let srv=D3D11_SHADER_RESOURCE_VIEW_DESC{Format:desc.Format,ViewDimension:D3D_SRV_DIMENSION_TEXTURE2DARRAY,Anonymous:D3D11_SHADER_RESOURCE_VIEW_DESC_0{Texture2DArray:D3D11_TEX2D_ARRAY_SRV{MostDetailedMip:0,MipLevels:levels,FirstArraySlice:0,ArraySize:slices[group]}}};let mut view=None;self.device.CreateShaderResourceView(&texture,Some(&srv),Some(&mut view))?;self.live_atlas[group]=Some((texture,view.unwrap()));}Ok(())}}
 pub fn live_upload(&self,group:usize,slice:u32,chain:&[image::RgbaImage]){let Some((texture,_))=&self.live_atlas[group]else{return;};let levels=crate::mips::BUCKETS[group].ilog2()+1;for(level,im)in chain.iter().enumerate(){unsafe{self.context.UpdateSubresource(texture,level as u32+slice*levels,None,im.as_ptr().cast(),im.width()*4,0);}}}
 pub fn check(&self)->Result<()>{unsafe{self.device.GetDeviceRemovedReason()?;}Ok(())}
 pub fn mask(&mut self,f:impl Fn(&str)->bool){for b in &mut self.batches{b.enabled=f(&b.name);}}
 pub fn pixels(&self,texture:&ID3D11Texture2D)->Result<(u32,u32,Vec<u8>)>{unsafe{let mut desc=D3D11_TEXTURE2D_DESC::default();texture.GetDesc(&mut desc);desc.Usage=D3D11_USAGE_STAGING;desc.BindFlags=0;desc.CPUAccessFlags=D3D11_CPU_ACCESS_READ.0 as u32;let mut staging=None;self.device.CreateTexture2D(&desc,None,Some(&mut staging))?;let staging=staging.unwrap();self.context.CopyResource(&staging,texture);let mut map=D3D11_MAPPED_SUBRESOURCE::default();self.context.Map(&staging,0,D3D11_MAP_READ,0,Some(&mut map))?;let mut bytes=vec![0u8;(desc.Width*desc.Height*4)as usize];for y in 0..desc.Height as usize{let row=slice::from_raw_parts((map.pData as *const u8).add(y*map.RowPitch as usize),desc.Width as usize*4);bytes[y*desc.Width as usize*4..(y+1)*desc.Width as usize*4].copy_from_slice(row);}self.context.Unmap(&staging,0);Ok((desc.Width,desc.Height,bytes))}}
